-- Nursing Sciences 200 Level first semester; 14 courses, 22 units.
-- Source S column has numeric programme statuses; these core programme courses are compulsory.
create temp table nursing_requested on commit drop as
select * from jsonb_to_recordset($data$[{"level": 200, "semester": 1, "code": "ENT 211", "title": "Entrepreneurship and Innovation", "units": 2, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 2/0/0.", "position": 1}, {"level": 200, "semester": 1, "code": "AUE-GST 201", "title": "Philosophy of Education", "units": 1, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 1/0/0.", "position": 2}, {"level": 200, "semester": 1, "code": "ANA 201", "title": "Anatomy of Upper and Lower Limb", "units": 3, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 2/0/1. Programme course treated as compulsory; printed S column repeats unit values rather than a status letter.", "position": 3}, {"level": 200, "semester": 1, "code": "ANA 203", "title": "General and Systemic Embryology", "units": 2, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 2/0/0. Programme course treated as compulsory; printed S column repeats unit values rather than a status letter.", "position": 4}, {"level": 200, "semester": 1, "code": "AUE-ANA 205", "title": "Introductory Genetics and Genomics", "units": 1, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 1/0/0. Programme course treated as compulsory; printed S column repeats unit values rather than a status letter.", "position": 5}, {"level": 200, "semester": 1, "code": "PIO 201", "title": "Introductory Physiology and Blood", "units": 2, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 2/0/0. Programme course treated as compulsory; printed S column repeats unit values rather than a status letter.", "position": 6}, {"level": 200, "semester": 1, "code": "AUE-PIO 205", "title": "Physiology Practical I", "units": 1, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 0/0/3. Programme course treated as compulsory; printed S column repeats unit values rather than a status letter.", "position": 7}, {"level": 200, "semester": 1, "code": "BCH 201", "title": "General and Medical Biochemistry I", "units": 2, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 2/0/0. Programme course treated as compulsory; printed S column repeats unit values rather than a status letter.", "position": 8}, {"level": 200, "semester": 1, "code": "BCH 203", "title": "General and Medical Biochemistry I Practical", "units": 1, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 0/0/3. Programme course treated as compulsory; printed S column repeats unit values rather than a status letter.", "position": 9}, {"level": 200, "semester": 1, "code": "NSC 201", "title": "Foundation of Professional Nursing Practice I (including Introduction to Nursing Profession)", "units": 2, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 2/0/0. Programme course treated as compulsory; printed S column repeats unit values rather than a status letter.", "position": 10}, {"level": 200, "semester": 1, "code": "AUE-NSC 211", "title": "Foundation of Professional Nursing Practical I", "units": 1, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 0/0/3. Programme course treated as compulsory; printed S column repeats unit values rather than a status letter.", "position": 11}, {"level": 200, "semester": 1, "code": "NSC 203", "title": "Developmental Psychology", "units": 1, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 1/0/0. Programme course treated as compulsory; printed S column repeats unit values rather than a status letter.", "position": 12}, {"level": 200, "semester": 1, "code": "AUE-NSC 213", "title": "Nursing Theories", "units": 1, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 1/0/0. Programme course treated as compulsory; printed S column repeats unit values rather than a status letter.", "position": 13}, {"level": 200, "semester": 1, "code": "AUE-NSC 215", "title": "Politics and Governance in Nursing", "units": 2, "status": "C", "lecture_hours": null, "practical_hours": null, "elective_group": null, "note": "Source L/T/P contact periods: 2/0/0. Programme course treated as compulsory; printed S column repeats unit values rather than a status letter.", "position": 14}]$data$::jsonb) as r(level int,semester int,code text,title text,units int,status text,lecture_hours int,practical_hours int,elective_group text,note text,position int);
create temp table nursing_scope on commit drop as
select d.id department_id,d.university_id,l.id level_id,l.sort_order level,s.id semester_id,s.sort_order semester
from public.departments d join public.universities u on u.id=d.university_id
join public.levels l on l.university_id=u.id and l.active and l.sort_order in(200)
join public.academic_periods ap on ap.university_id=u.id and ap.label='2026/2027' and ap.active
join public.semesters s on s.academic_period_id=ap.id and s.active and s.sort_order in(1)
where d.name='Nursing Sciences' and d.active and u.slug='adeleke-university-ede-osun-state';
create temp table nursing_other on commit drop as select o.* from public.course_offerings o where not exists(select 1 from nursing_scope s where s.department_id=o.department_id and s.level_id=o.level_id and s.semester_id=o.semester_id);
create temp table nursing_existing on commit drop as select o.id,o.course_id,o.department_id,o.level_id,o.semester_id from public.course_offerings o join nursing_scope s using(department_id,level_id,semester_id);
create temp table nursing_enrollments on commit drop as select * from public.enrollments;
do $$ begin
if (select count(*) from nursing_scope)<>1 or (select count(*) from nursing_requested)<>14 then raise exception 'Nursing source/scope mismatch'; end if;
end $$;
insert into public.courses(code,title) select distinct code,title from nursing_requested on conflict(code) do nothing;
insert into public.curriculum_courses(university_id,department_id,level_id,semester_number,course_id,unit_count,requirement_status,position,source_reference,lecture_hours,practical_hours,elective_group,source_code,source_title)
select s.university_id,s.department_id,s.level_id,r.semester,c.id,r.units,r.status,r.position,'Nursing List of courses 100L to 500L (2026_2027 session).pdf. '||coalesce(r.note,''),r.lecture_hours,r.practical_hours,r.elective_group,case when r.code='AUE-GST 201' then 'AUE-GES 201' else r.code end,r.title
from nursing_requested r join nursing_scope s using(level,semester) join public.courses c on c.code=r.code
on conflict(department_id,level_id,semester_number,course_id) do update set unit_count=excluded.unit_count,requirement_status=excluded.requirement_status,position=excluded.position,source_reference=excluded.source_reference,lecture_hours=excluded.lecture_hours,practical_hours=excluded.practical_hours,elective_group=excluded.elective_group,source_code=excluded.source_code,source_title=excluded.source_title,active=true;
insert into public.course_offerings(course_id,university_id,department_id,level_id,semester_id,status,unit_count,requirement_status,lecture_hours,practical_hours,elective_group,source_code,source_title)
select c.id,s.university_id,s.department_id,s.level_id,s.semester_id,'published',r.units,r.status,r.lecture_hours,r.practical_hours,r.elective_group,case when r.code='AUE-GST 201' then 'AUE-GES 201' else r.code end,r.title
from nursing_requested r join nursing_scope s using(level,semester) join public.courses c on c.code=r.code
on conflict(course_id,department_id,level_id,semester_id) do update set status='published',unit_count=excluded.unit_count,requirement_status=excluded.requirement_status,lecture_hours=excluded.lecture_hours,practical_hours=excluded.practical_hours,elective_group=excluded.elective_group,source_code=excluded.source_code,source_title=excluded.source_title;
do $$ begin
if (select count(*) from nursing_requested r join nursing_scope s using(level,semester) join public.courses c on c.code=r.code join public.course_offerings o on o.course_id=c.id and o.department_id=s.department_id and o.level_id=s.level_id and o.semester_id=s.semester_id where o.status='published' and o.unit_count=r.units and o.requirement_status=r.status and o.source_title=r.title and o.elective_group is not distinct from r.elective_group and o.lecture_hours is not distinct from r.lecture_hours and o.practical_hours is not distinct from r.practical_hours)<>14 then raise exception 'Nursing offerings verification failed'; end if;
if exists(select * from nursing_other except select * from public.course_offerings) then raise exception 'Unrelated offerings changed'; end if;
if exists(select * from nursing_existing except select id,course_id,department_id,level_id,semester_id from public.course_offerings) then raise exception 'Existing Nursing IDs changed'; end if;
if exists(select * from nursing_enrollments except select * from public.enrollments) then raise exception 'Enrollments changed'; end if;
end $$;
